function source(array $b): array {$r=array_fill(0,22,'0');$r[2]='271080';$r[6]='Navy';$r[7]='Original body fabric';$r[8]='Single Jersey';$r[9]='Cotton';$r[10]='Buyer';$r[14]='1100';return ['rfd'=>['rows'=>[['n'=>2,'v'=>$r]]],'booking'=>['rows'=>$b],'cutting'=>['rows'=>[]]];}
