$b=[book(2,'Single Jersey','800','180',ref:'B1'),book(3,'Single Jersey','200','200',ref:'B2')];$m=Ekwl\fdrBuild(source($b),$ops,$identity);ok(count($m['rows'])===2,'GSM variants are distinct');ok(array_sum(array_map(fn($r)=>(int)$r[13],$m['rows']))===1000,'No booking multiplication');foreach($m['rows']as $r)ok($r[6]==='—','Do not spread one unqualified receipt across GSM variants');foreach($m['evidence']as $e)ok($e['receipt_candidates']===[2],'Ambiguous receipts retain candidate source refs');
