$b=[book(2,'Single Jersey','1000'),book(3,'Single Jersey','1200',reason:'Revised total')];$m=Ekwl\fdrBuild(source($b),$ops,$identity);ok($m['evidence'][0]['reconciliation']['type']==='review','Revision cannot be inferred without stable revision/status identity');
